// .lighthouserc-mobile.cjs
// Mobile Lighthouse CI configuration for Date My Dish — PR gate
// URLs are generated by scripts/generate-lighthouse-urls.cjs --mode=post-types

const fs = require('fs');
const path = require('path');

let urls;
try {
  urls = JSON.parse(
    fs.readFileSync(path.join(__dirname, '.lighthouse-urls.json'), 'utf8')
  );
} catch {
  // Fallback if URL generation hasn't run
  urls = ['http://localhost:8788/en/', 'http://localhost:8788/fr/'];
}

module.exports = {
  ci: {
    collect: {
      startServerCommand: 'npx wrangler dev --port 8788',
      startServerReadyPattern: 'Ready on',
      startServerReadyTimeout: 30000,
      url: urls,
      numberOfRuns: 3,
      settings: {
        chromeFlags: '--no-sandbox --disable-dev-shm-usage',
        // No preset = Lighthouse mobile default (4x CPU throttle, simulated slow 4G)
        blockedUrlPatterns: [
          'https://s.pinimg.com/*',
          'https://ct.pinterest.com/*',
          'https://static.cloudflareinsights.com/*',
          'https://cloudflareinsights.com/*',
        ],
      },
    },
    // Performance budgets (docs/editorial-publishing-system.md): mobile
    // performance 95+, LCP <= 2.5 s, CLS <= 0.05. Every assertion is an
    // error, so a regression blocks the PR. Medians over numberOfRuns smooth
    // out runner noise.
    assert: {
      assertions: {
        'categories:performance': ['error', { minScore: 0.95, aggregationMethod: 'median-run' }],
        'categories:accessibility': ['error', { minScore: 0.9, aggregationMethod: 'median-run' }],
        'categories:best-practices': ['error', { minScore: 0.9, aggregationMethod: 'median-run' }],
        'categories:seo': ['error', { minScore: 0.9, aggregationMethod: 'median-run' }],
        'largest-contentful-paint': ['error', { maxNumericValue: 2500, aggregationMethod: 'median-run' }],
        'cumulative-layout-shift': ['error', { maxNumericValue: 0.05, aggregationMethod: 'median-run' }],
      },
    },
    upload: {
      target: 'temporary-public-storage',
    },
  },
};
